Ext._define('common.siatu.chamado.ItemBaseConhecimento.Window', {
    extend: 'core.RestfulWindow',

    rest: 'common.siatu.chamado.ItemBaseConhecimento.Restful',

    width: 450,

    getComboFilter: function() {
        if(!this._comboFilter) {
            this._comboFilter = Ext._create('core.fields.ComboField', {
                rest: 'common.siatu.BaseConhecimento.objeto.Restful',
                fieldLabel: 'Objeto',
                hiddenName: 'objeto',
                triggerAction: 'all',
                lazyRender: true,
                lazyInit: true,
                displayField: 'descricao',
                width: 325,
            });

            this._comboFilter.on({
                scope: this,
                changevalid:function(combo, id, start, valid) {
                    if (valid == true){
                        this.getComboFilterModelo().setPreFilter([
                            {property:'objetos',value: combo.getValue(), stage: 0},
                        ])
                        this.getComboFilterModelo().reset()
                        this.getComboFilterModelo().getStore().load({});
                        this.getBaseConhecimentoField().setPreFilter([
                            {property:'objeto',value: combo.getValue(), stage: 0},
                        ])
                        this.getBaseConhecimentoField().getComboField().getStore().load({});
                    }
                }
            });
        }
        return this._comboFilter;
    },

    getComboFilterModelo: function() {
        if(!this._comboFilterModelo) {
            this._comboFilterModelo = Ext._create('core.fields.ComboField', {
                rest: 'common.siatu.BaseConhecimento.modelo.Restful',
                fieldLabel: 'Modelo',
                hiddenName: 'modelo',
                triggerAction: 'all',
                lazyRender: true,
                lazyInit: true,
                displayField: 'descricao',
                width: 325,
            });

            this._comboFilterModelo.on({
                scope: this,
                change: function(combo, newValue, oldValue) {
                    this.getBaseConhecimentoField().setPreFilter([
                        {property:'objeto',value: this.getComboFilter().getValue(), stage: 0},
                        {property:'modelo',value:newValue, stage: 1},
                    ])
                    this.getBaseConhecimentoField().getComboField().getStore().load({})
                }
            });
        }
        return this._comboFilterModelo;
    },

    getBaseConhecimentoField: function(){
        if(!this._baseConhecimento){
            this._baseConhecimento = Ext._create('core.fields.AutocompleteField', {
                rest: 'common.siatu.BaseConhecimento.Restful',
                name: 'base_conhecimento',
                fieldLabel: 'Item',
                displayField: 'problema',
                allowBlank: true,
                width: 325,
                gridConfig: {
                    allowUpdate: false,
                    allowRemove: false,
                    hideItemsToolbar: ['edit', 'remove', 'download'],
                }
            });
        }

        return this._baseConhecimento;
    },

    getFormPanel: function(cfg) {
        if(!this._formPanel){
            var items;
            if (cfg.action == 'create') {
                items = [
                    this.getComboFilter(),
                    this.getComboFilterModelo(),
                    this.getBaseConhecimentoField()
                ]
            }
            else {
                items = [
                    {
                        xtype: 'textfield',
                        name: 'objeto_string',
                        fieldLabel: 'Objeto',
                        width: 475,
                        readOnly: true,
                    },
                    {
                        xtype: 'textfield',
                        name: 'modelo_string',
                        fieldLabel: 'Modelo',
                        width: 475,
                        readOnly: true,
                    },
                    {
                        xtype: 'textarea',
                        name: 'problema',
                        fieldLabel: 'Problema',
                        width: 476,
                        readOnly: true,
                    },
                    {
                        xtype: 'ckeditor',
                        name: 'solucao',
                        fieldLabel: 'Solução',
                        width: 476,
                        toolbar: [],
                        height: 140,
                    },
                ]
            }
            items = items.concat([{
                xtype: 'textfield',
                name: 'info',
                fieldLabel: 'Quantidade',
                width: (cfg.action == 'create') ? 325 : 475,
            }])

            this._formPanel = Ext._create('Ext.form.FormPanel', {
                border: false,
                frame: true,
                labelWidth: 80,
                items: items,
            });
        }

        return this._formPanel;
    },

    getButtons: function(cfg) {
        if(!this._buttons) {
            this._buttons = [
                {
                    text: 'Fechar',
                    scope: this,
                    handler: this.destroy
                }
            ];

            if(!cfg.disableSave)
                this._buttons = [{
                    text: 'Salvar',
                    scope: this,
                    handler: this.save,
                    handler: function() { this.save(true) }
                }].concat(this._buttons);

            if(cfg.action == 'create' && !cfg.disableSaveAndNew)
                this._buttons = [{
                    text: 'Salvar e novo',
                    scope: this,
                    handler: function() { this.save(false) }
                }].concat(this._buttons);
        }

        return this._buttons;
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});
        if (cfg.action == 'update')
            this.width = 590

        if (Ext.util.Cookies.get('siatu-area-informatica') != null)
            this.filtroInformatica = Ext.decode(Ext.util.Cookies.get('siatu-area-informatica'));
        else
            this.filtroInformatica = false;

        common.siatu.chamado.ItemBaseConhecimento.Window.superclass.constructor.call(this, cfg);

        this.getComboFilter().setPreFilter([
            {property: 'informatica',value: this.filtroInformatica, stage: 1000}
        ])

        this.getComboFilterModelo().setPreFilter([
            {property: 'objetos',value: null, stage: 0}
        ])
    }
});

/*
 * src: /app/root/common/static/siatu/chamado/ItemBaseConhecimento/Grid.js
 */
/**
 *
 **/
Ext._define('common.siatu.chamado.ItemBaseConhecimento.Grid', {
    extend: 'core.RestfulGrid',

    restWindow: 'common.siatu.chamado.ItemBaseConhecimento.Window',

    keywordFieldMessage: 'Objeto, problema ou solução',

    getColumnModel: function(){
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    {header: 'Codigo', dataIndex: 'base_conhecimento', width: 50, sortable:true},
                    {header: 'Objeto', dataIndex: 'objeto_string', width: 95, sortable:true},
                    {header: 'Problema', dataIndex: 'problema', width: 135},
                    {header: 'Solução', dataIndex: 'solucao', width: 135},
                    {header: 'Qtde', dataIndex: 'info', id: 'autoExpandColumn'}
                ]
            );

        return this._columnModel;
    },

    updateItem: function(record) {
        if(!this.allowUpdate)
            return

        if(record instanceof Ext.Button)
            record = undefined;

        var selected = core.nullValue(record, this.getSelectionModel().getSelected());

        if(selected) {
            this.factoryRestfulWindow({
                action: 'update',
                oId: selected.get('pk'),
                disableSave: this.disableSave,
                values: selected.data,
                params: this.getParams(),
                callback: {
                    success: {
                        scope: this,
                        fn: function() {
                            this.getStore().reload();
                        }
                    }
                }
            }).show();
        }
        else
            Ext.Msg.show({
                title: 'Editando',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Primeiro selecione um item para editar.'
            });
    },

    getConfigItemsToolbar: function(cfg){
        hideItems = cfg.hideItemsToolbar || this.hideItemsToolbar;
        if(!this._configItemsToolbar){
            this._configItemsToolbar = [];
            if(hideItems.indexOf('add') < 0){
                this._configItemsToolbar.push(
                    {
                        text: 'Novo',
                        iconCls: 'icon-core icon-core-add',
                        scope: this,
                        handler: this.createItem,
                    }
                );
            }
            if(hideItems.indexOf('edit') < 0){
                this._configItemsToolbar.push(
                    {
                        text: 'Editar',
                        iconCls: 'icon-core icon-core-edit',
                        scope: this,
                        handler: this.updateItem,
                    }
                );
            }
            if(hideItems.indexOf('remove') < 0){
                this._configItemsToolbar.push(
                    {
                        text: 'Remover',
                        iconCls: 'icon-core icon-core-delete',
                        scope: this,
                        handler: this.removeItems,
                    }
                );
            }

            this._configItemsToolbar.push('-');

            if(hideItems.indexOf('base_conhecimento') < 0){
                this._configItemsToolbar.push('Buscar:');
                this._configItemsToolbar.push(this.getBaseConhecimentoField());
                this._configItemsToolbar.push('-');
            }

            if(hideItems.indexOf('search') < 0){
                this._configItemsToolbar.push('Buscar por :');
                this._configItemsToolbar.push(' ');
                this._configItemsToolbar.push(this.getKeywordField());
                this._configItemsToolbar.push('-');
            }

            if(hideItems.indexOf('download') < 0){
                this._configItemsToolbar.push('->');
                this._configItemsToolbar.push('-');
                this._configItemsToolbar.push(
                    {
                        text: 'Download',
                        iconCls: 'icon-core icon-core-csv',
                        scope: this,
                        handler: this.doDownload
                    }
                );
            }
        }

        return this._configItemsToolbar;
    },

    getBaseConhecimentoField: function(){
        if(!this._baseConhecimento){
            if (Ext.util.Cookies.get('siatu-area-informatica') != null)
                this.filtroInformatica = Ext.decode(Ext.util.Cookies.get('siatu-area-informatica'));
            else
                this.filtroInformatica = false;
            this._baseConhecimento = Ext._create('core.fields.AutocompleteField', {
                rest: 'common.siatu.BaseConhecimento.Restful',
                name: 'base_conhecimento',
                fieldLabel: 'Item',
                emptyText: 'Selecione um item para inserir',
                allowBlank: true,
                width: 255,
                preFilter: [{property: 'objeto__informatica', value: this.filtroInformatica, stage: 1000}],
                gridConfig: {
                    allowUpdate: false,
                    allowRemove: false,
                    listeners: {
                        scope: this,
                        render: function(grid){
                            tbar = grid.getToolbar()
                            tbar.remove(tbar.getComponent(1))//Editar
                            tbar.remove(tbar.getComponent(1))//Remover
                        },
                    }
                },
                comboListeners: {
                    scope: this,
                    changevalid:function(cmb, id, start, valid, old) {
                        if(valid == true){
                            base_conhecimento = cmb.getValue()
                            var rest = this.factoryRestful();
                            rest.create(
                                {
                                    params: {
                                        chamado: this.getParams().chamado,
                                        base_conhecimento: base_conhecimento,
                                    },
                                    externalCallback: {
                                        success: {
                                            scope: this,
                                            fn: function(){
                                                this.getStore().load({})
                                            }
                                        }
                                    }
                                }
                            );
                            this.OldValueCombo = cmb.getValue()
                            this.getBaseConhecimentoField().reset()
                        }

                    },
                },
            });
        }

        return this._baseConhecimento;
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});

        common.siatu.chamado.ItemBaseConhecimento.Grid.superclass.constructor.call(this, cfg);
    }

})

