Ext._define('common.siatu.chamado.status.concluirWindow', {
    extend: 'core.RestfulWindow',

    rest: 'common.siatu.chamado.Restful',

    width: 705,

    getFormPanel: function() {
        if(!this._formPanel)
            this._formPanel = Ext._create('Ext.form.FormPanel', {
                border: false,
                frame: true,
                labelAlign: 'top',
                items: [
                    {
                        xtype: 'ckeditor',
                        name: 'relatorio',
                        fieldLabel: 'Relatório de diagnóstico (4000 caracteres)',
                        toolbar: [
                            ['Source'], ['PasteFromWord'], ['Scayt'],
                            ['Link','Unlink','Anchor'],
                            ['NumberedList','BulletedList'],
                            ['Bold','Italic','Underline', 'Styles','Format', 'TextColor','BGColor']
                        ],
                        autoScroll: true,
                        width: 675,
                        height: 215
                    },
                    {
                    xtype: 'checkbox',
                    width: 295,
                    hideLabel: true,
                    name: 'nao_institucional',
                    boxLabel: 'Não institucional',
                    inputValue:'true',
                    allowBlank: true,
                },
                ]
            });

        return this._formPanel;
    },

    getButtons: function(cfg) {
        if(!this._buttons) {
            this._buttons = [
                {
                    text: 'Salvar relatório',
                    scope: this,
                    handler: this.save,
                },
                {
                    text: "Salvar e concluir",
                    handler: function() {
                        Ext.Msg.show({
                            scope: this,
                            title: 'PERGUNTA',
                            icon: Ext.Msg.QUESTION,
                            buttons: Ext.Msg.OKCANCEL,
                            msg: 'Deseja realmente concluir o chamado ' + this.values.identificacao + ' ?',
                            fn: function(button) {
                                if(button == 'ok'){
                                    this.salvar_concluir();
                                }
                            },
                        });
                    },
                    scope: this
                },
                {
                    text: 'Fechar',
                    scope: this,
                    handler: this.destroy
                }
            ];
        }

        return this._buttons;
    },

    salvar_concluir: function() {
        var form = this.getFormPanel().getForm();
        var restChamado = this.factoryRestful();
        restChamado.update(
            this.oId,
            {
                externalCallback: {
                    scope: this,
                    success: {
                        scope: this,
                        fn: function() {
                            this.concluir();
                            this.destroy();
                        }
                    }
                },
                params: Ext.applyIf(
                    form.getValues(),
                    this.getParams()
                )
            },
            {
                el: this.getEl(),
                waitMessage: 'Persistindo os dados.'
            }
        );
    },


    concluir: function() {
        var rest = Ext._create('common.siatu.chamado.status.Restful', {});
        var cfg = {
            externalCallback: this.status_callback,
            params: {
                status: 4,
                chamado: this.oId,
                insert: true,
            } //status 4 == Aguardando avaliação representado como concluido para atendentes..
        };
        rest.create(
            cfg,
            {
                el: this.getEl(),
                waitMessage: 'Persistindo os dados.'
            }
        );
    }
});

/*
 * src: /app/root/common/static/siatu/chamado/status/Window.js
 */
/**
 *
 **/
Ext._define('common.siatu.chamado.status.Window', {
    extend: 'core.RestfulWindow',

    rest: 'common.siatu.chamado.status.Restful',

    // width: 360,
    width: 270,

    getStatusField: function(){
        if(!this._status){
            this._status = Ext._create('Ext.form.ComboBox',{
                fieldLabel: 'Status',
                hiddenName: 'status',
                width: 240,
                allowBlank: false,
                triggerAction: 'all',
                store: [
                        [3, 'Em atendimento','icon-siatu icon-siatu-atendimento'],
                        [8, 'Em Viagem','icon-siatu icon-siatu-viagem'],
                        [6, 'Terceirizada','icon-siatu icon-siatu-terceirizada'],
                        [7, 'Garantia','icon-siatu icon-siatu-garantia'],
                        [10, 'Aguardando entrega','icon-siatu icon-siatu-entrega'],
                        [11, 'Em manutenção','icon-siatu icon-siatu-manutencao'],
                        [4, 'Concluído','icon-siatu icon-siatu-concluido'], //Status  '4 - Aguardando avaliacao' representado como concluido para atendente
                    ],
                tpl: '<tpl for="."><div class="x-combo-list-item {field3}" style="height: 13px;">&nbsp &nbsp &nbsp &nbsp{' +
                    'field2'+ '}</div></tpl>',
            });

            this._status.on({
                scope: this,
                select: function(combo,record,index) {
                    if(record.get('field2')=='Terceirizada'){
                        this.getTerceirizadaField().enable();
                        this.getTerceirizadaField().show();
                    }
                    else{
                        this.getTerceirizadaField().disable();
                        this.getTerceirizadaField().hide();
                    }

                    if(record.get('field2')=='Garantia' || record.get('field2')=='Em Viagem' || record.get('field2')=='Terceirizada'){
                        this.getPrevisaoFimField().enable().show();
                    }
                    else{
                        this.getPrevisaoFimField().disable().hide();
                    }
                }
            });
        }

        return this._status;
    },

    getTerceirizadaField: function(){
        if(!this._terceirizada){
            this._terceirizada = Ext._create('core.fields.AutocompleteField', {
                rest: 'common.siatu.terceirizada.Restful',
                name: 'terceirizada',
                fieldLabel: 'Terceirizada',
                displayField: 'nome',
                allowBlank: false,
                hidden: this.values.status_display != 'Terceirizada',
                disabled: this.values.status_display != 'Terceirizada',
                gridConfig:{
                    columnAction: false,
                    allowUpdate: false,
                    allowRemove: false,
                    listeners:{
                        render: function(grid) {
                            tbar = grid.getToolbar();
                            tbar.remove(tbar.getComponent(1)); //Editar
                            tbar.remove(tbar.getComponent(1)); //Remover
                        }
                    }
                }
            });
        }

        return this._terceirizada;
    },

    getObservacaoField: function(){
        if(!this._observacao){
            this._observacao = Ext._create('Ext.form.TextField', {
                name: 'motivo',
                fieldLabel: 'Observação',
                width: 225,
            });
        }

        return this._observacao;
    },

    getPrevisaoFimField: function() {
        if(!this._previsao){
            this._previsao = Ext._create('Ext.form.DateField', {
                fieldLabel: 'Previsão de fim',
                name: 'previsao_fim',
                allowBlank: true,
                hidden: true,
                disabled: true,
            });
        }

        return this._previsao;
    },

    getFormPanel: function() {
        if(!this._formPanel)
            this._formPanel = Ext._create('Ext.form.FormPanel', {
                border: false,
                frame: true,
                labelAlign: 'top',
                items: [
                    this.getStatusField(),
                    this.getTerceirizadaField(),
                    this.getPrevisaoFimField(),
                    this.getObservacaoField(),

                ]
            });

        return this._formPanel;
    },

    setParam: function(key, value) {
        this.params = core.nullValue(this.params, {});
        this.params[key] = value;
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});

        if (cfg.values)
            this.values = cfg.values;
        else{
            this.values = {};
        }

        Ext.applyIf(
            cfg,
            {
            }
        );

        Ext.apply(
            cfg,
            {
            }
        );
        common.siatu.chamado.status.Window.superclass.constructor.call(this, cfg);

        if(this.values.status_display == 'Garantia' || this.values.status_display == 'Terceirizada' || this.values.status_display == 'Em Viagem'){
            this.getPrevisaoFimField().enable().show();
        }
        if(this.action=='create'){
            this.setParam('insert',true);
        }
        else {
            delete this.params['insert'];
        }
    }
});

/*
 * src: /app/root/common/static/siatu/chamado/status/Grid.js
 */
/**
 *
 **/
Ext._define('common.siatu.chamado.status.Grid', {
    extend: 'core.RestfulGrid',

    restWindow: 'common.siatu.chamado.status.Window',

    keywordFieldMessage: '',

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: '', dataIndex: 'icon', width:25, renderer: common.siatu.rendererIconGrid},
                    {header: 'Status', dataIndex: 'status_display', width: 160},
                    {header: 'Data de início', dataIndex: 'data_inicio', width: 100},
                    {header: 'Previsão de fim', dataIndex: 'previsao_fim', width: 100},
                    {header: 'Terceirizada', dataIndex: 'terceirizada_string', width: 160},
                    {header: 'Observação', dataIndex: 'motivo', id: 'autoExpandColumn'},
                ]
            );

        return this._columnModel;
    },

    getActionColumn: function() {
        if(!this._actionColumn)
            this._actionColumn = Ext._create('Ext.grid.ActionColumn', {
                width: 65,
                scope: this,
                items: [
                    {
                        iconCls: 'icon-16px icon-core icon-core-edit',
                        tooltip: 'Editar item.',
                        handler: function(action, index) {
                            var record = this.getStore().getAt(index);
                            record && this.updateItem(record);
                        }
                    },
                ]
            });

        return this._actionColumn;
    },

    createItem: function(values) {
        if(!this.allowCreate)
            return;

        values = core.nullValue(values, {});

        this.factoryRestfulWindow({
            action: 'create',
            params: this.getParams(),
            values: values,
            callback: this.callback
        }).show();
    },

    updateItem: function(record) {
        if(!this.allowUpdate)
            return;

        if(record instanceof Ext.Button)
            record = undefined;

        var selected = core.nullValue(record, this.getSelectionModel().getSelected());
        // se Status for Aberto ou Aguardando Atendimento, então não pode editar
        if ( (selected.get('status') == 1) || (selected.get('status') == 2) ){
            console.debug('Não é possivel editar este status');
            return;
        }

        if(selected) {
            this.factoryRestfulWindow({
                action: 'update',
                oId: selected.get('pk'),
                values: selected.data,
                params: this.getParams(),
                callback: this.callback
            }).show();
        }
        else
            Ext.Msg.show({
                title: 'Editando',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Primeiro selecione um item para editar.'
            });
    },

    removeItems: function(record) {
        if(!this.allowRemove)
            return;

        var selection;

        if(!(record instanceof Ext.Button))
            selection = [record];
        else
            selection = this.getSelectionModel().getSelections();

        var pk;
        var rest = this.factoryRestful();

        if(selection.length == 1) {
            pk = selection[0].get('pk');

            rest.remove(
                pk,
                {
                    externalCallback: this.callback
                },
                {
                    el: this.getEl(),
                    msg: 'Removendo item.'
                }
            );
        }
        else if(selection.length > 1) {
            pk = selection.map(function(selected) { return selected.get('pk'); });

            rest.remove(
                false,
                {
                    params: {
                        filter: Ext.encode([
                            {property: 'pk__in', value: pk}
                        ])
                    },
                    externalCallback: {
                        success: {
                            fn: function() { this.getStore().reload(); },
                            scope: this
                        }
                    }
                },
                {
                    el: this.getEl(),
                    msg: 'Removendo item.'
                }
            );
        }
        else
            Ext.Msg.show({
                title: 'Removendo',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Não foi selecionado nenhum item para remoção.'
            });
    },

    getToolbar: function(cfg) {
        if(!this._toolbar) {
            this._toolbar = Ext._create('Ext.Toolbar', {
                style: cfg.toolbarStyle,
                items: [
                    {
                        text: 'Novo',
                        iconCls: 'icon-core icon-core-add',
                        scope: this,
                        handler: this.createItem
                    },
                    {
                        text: 'Editar',
                        iconCls: 'icon-core icon-core-edit',
                        scope: this,
                        handler: this.updateItem
                    },
                    '-',
                    'Buscar por :',
                    ' ',
                    this.getKeywordField(),
                    '-',
                    '->'
                ]
            });

            var filterMenu = this.getFilterMenu();
            if(filterMenu)
                this._toolbar.add([
                    '-',
                    {
                        text: 'Filtro',
                        iconCls: 'icon-patrimonio icon-pat-filter',
                        menu: filterMenu
                    }
                ]);
        }

        return this._toolbar;
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.applyIf(
            cfg,
            {
                callback: {
                    success: {
                        scope: this,
                        fn: function() {
                            this.getStore().reload();
                        }
                    }
                }
            }
        );
        Ext.apply(cfg,{
            columnAction: false,
        });
        common.siatu.chamado.status.Grid.superclass.constructor.call(this, cfg);
    }

});

/*
 * src: /app/root/common/static/siatu/chamado/transferencia/PanelGerentes.js
 */
/**
 *
 **/
Ext._define('common.siatu.chamado.transferencia.PanelGerentes', {
    extend: 'Ext.Panel',

    setParam: function(key, value) {
        this.params = core.nullValue(this.params, {});
        this.params[key] = value;
    },

    getParams: function() {
        return core.nullValue(this.params, {});
    },

    setChamado: function(pk) {
        this.ChamadoId = pk;
    },

    getChamado: function() {
        return this.ChamadoId;
    },

    getListaAtendenteGrid: function() {
        if(!this._listaAtendenteServGrid){
             this._listaAtendenteServGrid = Ext._create('common.siatu.atendente.Grid', {
                flex: 1.0,
                border: true,
                gridAutoLoad: false,
                title:'Lista de atendentes do chamado',
                columnAction: false,
                allowCreate: false,
                allowRemove: false,
                hideItemsToolbar: ['add', 'edit', 'remove', 'download', 'notificacao']
            });

            this._listaAtendenteServGrid.getStore().setDefaultSort('username','ASC');

            this._listaAtendenteServGrid.getKeywordField().setWidth(210);

            var fbar = this._listaAtendenteServGrid.getFooterbar();
            fbar.remove(fbar.getComponent(10)); //Atualizar Store

         }

         return this._listaAtendenteServGrid;
    },

    getAtendenteGrid: function() {
        if(!this._atendenteGrid) {
            this._atendenteGrid = Ext._create('common.siatu.atendente.Grid', {
                title: 'Atendentes',
                flex: 1.0,
                border: true,
                columnAction:false,
                layout: 'fit',
                gridAutoLoad: false,
                allowCreate: false,
                allowRemove: false,
                hideItemsToolbar: ['add', 'edit', 'remove', 'download', 'notificacao']
            });

            this._atendenteGrid.getKeywordField().setWidth(210);

            var fbar = this._atendenteGrid.getFooterbar();
            fbar.remove(fbar.getComponent(10)); //Atualizar Store
        }

        return this._atendenteGrid;
    },

    setStoreAtendenteGrid: function(chamado) {
        rest = Ext._create('common.siatu.atendente.Restful',{});
        this.getAtendenteGrid().setStore(
            Ext._create('Ext.data.Store', {
                    proxy: Ext._create('Ext.data.HttpProxy', {
                        api: {
                            read: core.callAction("SiatuAtendente", "action_atendentes_not_in_chamado", chamado)
                        },
                        disableCaching: false,
                        defaultHeaders: rest.defaultHeaders,
                    }),
                    reader: Ext._create('Ext.data.JsonReader', {
                        idProperty: 'pk',
                        root: 'collection',
                        totalProperty: 'count',
                        successProperty: 'success',
                        messageProperty: 'message',
                        fields: rest.getFields()
                    }),
                    autoLoad: true
                })
        );
        var store = this.getAtendenteGrid().getStore()
        store.setDefaultSort('username','ASC')
        this.getAtendenteGrid().reconfigure(store,this.getAtendenteGrid().getColumnModel())
    },

    addSelectedAtendente: function() {
        var items = new Array();
        var store1 = this.getListaAtendenteGrid().getStore();
        var store2 = this.getAtendenteGrid().getStore();
        var selections = this.getAtendenteGrid().getSelectionModel().getSelections();

        if(selections.length==0){
            console.debug('Não há atendente selecionado para adicionar ao chamado')
            return '';
        }

        selections.map(
            function(record) {
                store1.addSorted(record)
                store2.remove(record)
            }
        );

        this.getAtendenteGrid().getView().refresh()
        this.getListaAtendenteGrid().getView().refresh()

        var rec=store1.getRange()

        for (i=0; i<rec.length; i++){
            items.push(rec[i].get('pk'))
        }

        this.setParam('atendente_posterior',items)
    },

    removeSelectedAtendente: function() {
        var items = new Array();
        var store1 = this.getListaAtendenteGrid().getStore();
        var store2 = this.getAtendenteGrid().getStore();
        var selections = this.getListaAtendenteGrid().getSelectionModel().getSelections();

        if(selections.length==0){
            console.debug('Não há atendente selecionado para remover do chamado')
            return '';
        }

        selections.map(
            function(record) {
                store1.remove(record)
                store2.addSorted(record)
            }
        );

        this.getAtendenteGrid().getView().refresh()
        this.getListaAtendenteGrid().getView().refresh()

        var rec=store1.getRange()

        for (i=0; i<rec.length; i++){
            items.push(rec[i].get('pk'))
        }


        this.setParam('atendente_posterior',items)
    },

    getControlPanel: function() {
        if(!this._controlPanelAtendente)
            this._controlPanelAtendente = Ext._create('Ext.Panel', {
                width: 40,
                frame: true,
                layout: 'vbox',
                bodyStyle: {
                    'border-top': 0,
                    'border-bottom': 0
                },
                items: [
                    {
                        xtype: 'panel',
                        flex: 1.0
                    },
                    {
                        xtype: 'button',
                        text: '',
                        iconCls: 'icon-siatu icon-siatu-move-right',
                        width: 28,
                        height: 30,
                        style: {
                            padding: '2px 0 0 0'
                        },
                        scope: this,
                        handler: function() {  this.addSelectedAtendente() }
                    },
                    {
                        xtype: 'panel',
                        height:10,
                    },
                    {
                        xtype: 'button',
                        text: '',
                        iconCls: 'icon-siatu icon-siatu-move-left',
                        width: 28,
                        height: 30,
                        style: {
                            padding: '2px 0 0 0'
                        },
                        scope: this,
                        handler: function() { this.removeSelectedAtendente()}
                    },
                    {
                        xtype: 'panel',
                        flex: 1.0
                    }
                ]
            });

        return this._controlPanelAtendente;
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.apply(
            cfg,
            {
                layout:'form',
                labelWidth:50,
                items:[{
                    region: 'center',
                    layout: 'hbox',
                    split:true,
                    height:310,
                    bodyStyle: {
                        'border-left': 0,
                        'border-right': 0,
                    },
                    // layoutConfig: {
                    // align: 'stretch',
                    // },
                    defaults:{
                        height:300,
                    },
                    items:[
                        this.getAtendenteGrid(),
                        this.getControlPanel(),
                        this.getListaAtendenteGrid(),
                    ]
                    },
                    {
                        region: 'south',
                        xtype: 'textfield',
                        name: 'motivo',
                        fieldLabel: 'Motivo',
                        width: 700,
                        allowBlank: false,
                    }
                ]
            }
        );

        common.siatu.chamado.transferencia.PanelGerentes.superclass.constructor.call(this, cfg);
        this.setParam('atendente_posterior','old')
    }

});
