                flex: 1.0,
                border: false,
                gridAutoLoad: false,
                title:'Atendentes do chamado',
                columnAction: false,
                region: 'center',
                allowCreate: false,
                allowRemove: false,
                hideItemsToolbar: ['add', 'edit', 'remove', 'download', 'notificacao']
