/*
 * src: /app/root/common/static/saci/attendance/Restful.js
 */
Ext._define('common.saci.attendance.Restful', {
    extend: 'core.Restful',

    resource: 'SACIAttendanceRestful',

    accessControl: function(pk, values, cbSuccess, cbFailure, cbCallback) {
        this.doRequest(
            this.getRoute(
                'access_control',
                pk,
                'POST',
                {
                    params: values,
                    scope: this,
                    callback: function() {
                        core.invokeCallback((cbCallback || {fn: Ext.emptyFn}));
                    },
                    success: function(xhr) {
                        var rst = Ext.decode(xhr.responseText);

                        if(rst.success)
                            core.invokeCallback((cbSuccess || {fn: Ext.emptyFn}), rst);
                        else
                            core.invokeCallback((cbFailure || {fn: Ext.emptyFn}), rst.message);
                    },
                    failure: function() {
                        core.invokeCallback((cbFailure || {fn: Ext.emptyFn}), 'Recurso indisponivel no momento.');
                    }
                }
            )
        );
    },

    movement: function(pk, values, cbSuccess, cbFailure, cbCallback) {
        this.doRequest(
            this.getRoute(
                'movement',
                pk,
                'POST',
                {
                    params: values,
                    scope: this,
                    callback: function() {
                        core.invokeCallback((cbCallback || {fn: Ext.emptyFn}));
                    },
                    success: function(xhr) {
                        var rst = Ext.decode(xhr.responseText);

                        if(rst.success)
                            core.invokeCallback((cbSuccess || {fn: Ext.emptyFn}), rst);
                        else
                            core.invokeCallback((cbFailure || {fn: Ext.emptyFn}), rst.message);
                    },
                    failure: function() {
                        core.invokeCallback((cbFailure || {fn: Ext.emptyFn}), 'Recurso indisponivel no momento.');
                    }
                }
            )
        );
    },

    finalize: function(pk, values, cbSuccess, cbFailure, cbCallback) {
        this.doRequest(
            this.getRoute(
                'finalize',
                pk,
                'POST',
                {
                    params: values,
                    scope: this,
                    callback: function() {
                        core.invokeCallback((cbCallback || {fn: Ext.emptyFn}));
                    },
                    success: function(xhr) {
                        var rst = Ext.decode(xhr.responseText);

                        if(rst.success)
                            core.invokeCallback((cbSuccess || {fn: Ext.emptyFn}), rst);
                        else
                            core.invokeCallback((cbFailure || {fn: Ext.emptyFn}), rst.message);
                    },
                    failure: function() {
                        core.invokeCallback((cbFailure || {fn: Ext.emptyFn}), 'Recurso indisponivel no momento.');
                    }
                }
            )
        );
    },

    afterGenerateLawsuit: function(values, cbSuccess, cbFailure, cbCallback) {
        this.doRequest(
            this.getRoute(
                'after_generate_lawsuit',
                false,
                'POST',
                {
                    scope: this,
                    params: values,
                    callback: function() {
                        core.invokeCallback((cbCallback || {fn: Ext.emptyFn}));
                    },
                    success: function(xhr) {
                        var rst = Ext.decode(xhr.responseText);

                        if(rst.success)
                            core.invokeCallback((cbSuccess || {fn: Ext.emptyFn}), rst);
                        else
                            core.invokeCallback((cbFailure || {fn: Ext.emptyFn}), rst.message);
                    },
                    failure: function() {
                        core.invokeCallback((cbFailure || {fn: Ext.emptyFn}), 'Recurso indisponivel no momento.');
                    }
                }
            )
        );
    },

    checkToSign: function(pk, cbSuccess, cbFailure, cbCallback) {
        this.doRequest(
            this.getRoute(
                'check_to_sign',
                pk,
                'POST',
                {
                    scope: this,
                    callback: function() {
                        core.invokeCallback((cbCallback || {fn: Ext.emptyFn}));
                    },
                    success: function(xhr) {
                        var rst = Ext.decode(xhr.responseText);

                        if(rst.success)
                            core.invokeCallback((cbSuccess || {fn: Ext.emptyFn}), rst);
                        else
                            core.invokeCallback((cbFailure || {fn: Ext.emptyFn}), rst.message);
                    },
                    failure: function() {
                        core.invokeCallback((cbFailure || {fn: Ext.emptyFn}), 'Recurso indisponivel no momento.');
                    }
                }
            )
        );
    },

    sign: function(pkset, cbSuccess, cbFailure, cbCallback) {
        var emptyFailure = {
            fn: function(message) {
                Ext.Msg.show({
                    title: 'Finalizando documento',
                    msg: message,
                    icon: Ext.Msg.ERROR,
                    buttons: Ext.Msg.OK
                });
            }
        };

        this.doRequest(this.getRoute(
            'sign',
            false,
            'POST',
            {
                params: {
                    pkset: pkset
                },
                success: function(xhr) {
                    var rst = Ext.decode(xhr.responseText);

                    if(rst.success)
                        core.invokeCallback((cbSuccess || {fn: Ext.emptyFn}), rst.document);
                    else
                        core.invokeCallback((emptyFailure || {fn: Ext.emptyFn}), rst.message);

                },
                failure: function(xhr) {
                    core.invokeCallback((cbFailure || emptyFailure), 'Recurso indisponivel no momento.');
                },
                callback: function() {
                    core.invokeCallback((cbCallback || {fn: Ext.emptyFn}));
                }
            }
        ));
    },

    rendererDocument: function(pk, cbSuccess, cbFailure, cbCallback) {
        var emptyFailure = {
            fn: function(message) {
                Ext.Msg.show({
                    title: 'Buscando documento',
                    msg: message,
                    icon: Ext.Msg.ERROR,
                    buttons: Ext.Msg.OK
                });
            }
        };

        this.doRequest(this.getRoute(
            'renderer_document',
            pk,
            'GET',
            {
                success: function(xhr) {
                    var rst = Ext.decode(xhr.responseText);

                    if(rst.success)
                        core.invokeCallback((cbSuccess || {fn: Ext.emptyFn}), rst.document);
                    else
                        core.invokeCallback((emptyFailure || {fn: Ext.emptyFn}), rst.message);

                },
                failure: function(xhr) {
                    core.invokeCallback((cbFailure || emptyFailure), 'Recurso indisponivel no momento.');
                },
                callback: function() {
                    core.invokeCallback((cbCallback || {fn: Ext.emptyFn}));
                }
            }
        ));
    },

    getFields: function(cfg) {
        if(!this._fields)
            this._fields = common.saci.attendance.Restful.superclass.getFields.call(this, cfg).concat([
                {name: 'icons'},
                { type: "int",    name: "movement", useNull: true },
                { type: "int",    name: "person", useNull: true },
                { type: "string", name: "person_unicode" },
                { type: "int",    name: "destination", useNull: true },
                { type: "string", name: "destination_unicode" },
                { type: "int",    name: "represented", useNull: true },
                { type: "string", name: "represented_unicode" },
                { type: "bool",   name: "contains_represented" },
                { type: "bool",   name: "competence_others" },
                { type: "string", name: "feedback" },
                { type: "string", name: "story" },
                { type: "string", name: "subject" },
                { type: "date",   name: "created_at", dateFormat: "d/m/Y H:i" },
                { type: "date",   name: "signed_at", dateFormat: "d/m/Y H:i" },
                { type: "string", name: "signed_at_unicode" },
                { type: "date",   name: "modified_at", dateFormat: "d/m/Y H:i" },
                { type: "int",    name: "created_by", useNull: true },
                { type: "string", name: "created_by_unicode" },
                { type: "int",    name: "modified_by", useNull: true },
                { type: "string", name: "modified_by_unicode" },
                { type: "int",    name: "protocol", useNull: true },
                { type: "string", name: "protocol_unicode" },
                { type: "int",    name: "department", useNull: true },
                { type: "string", name: "department_unicode" },
                { type: "int",    name: "typology", useNull: true },
                { type: "string", name: "typology_unicode" },
                { type: "bool",   name: "confidential" },

                // Controle de Acesso (app document_access)
                { type: "int",    name: "control" },
                { type: "int",    name: "control_type" },
                { type: "bool",   name: "can_read" },
            ]);

        return this._fields;
    }
});

/*
 * src: /app/root/common/static/saci/attendance/Window.js
 */
Ext._define('common.saci.attendance.Window', {
    extend: 'core.RestfulWindow',

    rest: 'common.saci.attendance.Restful',

    width: 900,
    height: 600,

    loadAttachment: function(value) {
        if(value) {
            this.getAttachmentGrid().enable();
            this.getAttachmentGrid().setParam('attendance', value);
            this.getAttachmentGrid().setFilterProperty('attendance', value, 100);
        } else {
            this.getAttachmentGrid().disable();
            this.getAttachmentGrid().setParam('attendance', 0);
            this.getAttachmentGrid().setFilterProperty('attendance', 0, 100);
        }
    },

    getRepresentedField: function(cfg){
        if(!this._representedField){
            this._representedField = Ext._create('core.fields.AutocompleteField', {
                xtype: "rest-autocompletefield",
                fieldLabel: "Representado",
                allowBlank: true,
                rest: "rh.person.Restful",
                name: "represented",
                disabled: true,
            });
        }

        return this._representedField;
    },

    _isCheckedRepresented: function(cfg, checked){
        if(checked)
            this.getRepresentedField().enable();
        else{
            this.getRepresentedField().disable();
        }

        this.getRepresentedField().setValue('');
        this.getRepresentedField().getComboField().getStore().removeAll();
    },

    getTabFeedbackField: function(cfg) {
        if(!this._tabFeedbackField)
            this._tabFeedbackField = Ext._create('Ext.Panel',{
                layout: 'form',
                title: 'Parecer',
                border: false,
                frame: false,
                scope: this,
                autoHeight: true,
                disabled: true,
                items: [
                    {
                        allowBlank: true,
                        fieldLabel: "Parecer",
                        name: "feedback",
                        xtype: "ckeditor",
                        hideLabel: true,
                        height: 180,
                        submit: true,
                    }
                ]
            });
        return this._tabFeedbackField;
    },

    getStoryPanel: function(cfg) {
        if(!this._storyPanel)
            this._storyPanel = Ext._create('Ext.Panel',{
                layout: 'form',
                title: 'Relato do Cidadão',
                border: true,
                frame: false,
                scope: this,
                items: [
                    {
                        allowBlank: true,
                        fieldLabel: "Relato",
                        name: "story",
                        xtype: "ckeditor",
                        hideLabel: true,
                        height: 200,
                        submit: true,
                    }
                ]
            });
        return this._storyPanel;
    },

    getDepartmentField: function(cfg) {
        if(!this._departmentField){
            this._departmentField = Ext._create('core.fields.ComboField', {
                fieldLabel: 'Atuando por',
                hiddenName: 'department',
                displayField: 'description',
                store: Ext._create('Ext.data.Store', {
                    proxy: Ext._create('Ext.data.HttpProxy', {
                        url: core.callAction('EDOCManage', 'work_locations')
                    }),
                    reader: Ext._create('Ext.data.JsonReader', {
                        totalProperty: 'count',
                        root: 'collection',
                        fields: [
                            {name: 'pk', type: 'int'},
                            {name: 'description', type: 'string'},
                        ]
                    })
                }),
                width: 767,
                allowBlank: false
            });
        }

        return this._departmentField;
    },

    getTypologyField: function(cfg) {
        if(!this._typologyField)
            this._typologyField = Ext._create('core.fields.AutocompleteField',{
                xtype: "rest-autocompletefield",
                fieldLabel: "Público Alvo",
                allowBlank: false,
                rest: "common.saci.typology.Restful",
                name: "typology",
            });
        return this._typologyField;
    },

    getItemsMainPanel: function(cfg) {
        return [
            this.getDepartmentField(),
            this.getTypologyField(),
            {
                allowBlank: false,
                fieldLabel: "Assunto",
                name: "subject",
                xtype: "textfield",
                width: 767,

            },
            {
                xtype: 'checkbox',
                boxLabel: 'O Cidadão representa alguém?',
                labelSeparator: '&nbsp;',
                fieldLabel: '&nbsp;',
                allowBlank: true,
                name: 'contains_represented',
                listeners: {
                    scope: this,
                    check: this._isCheckedRepresented
                }
            },
            this.getRepresentedField(cfg),
            this.getControlContainer(cfg),
            this.getStoryPanel()
        ];
    },

    getAttachmentGrid: function(cfg) {
        if(!this._attachmentGrid)
            this._attachmentGrid = Ext._create('common.saci.attachment.Grid', {
                title: 'Anexos',
                gridAutoLoad: false,
                columnAction: false,
                height: 510,
                disabled: true
            });

        return this._attachmentGrid;
    },

    getMainPanel: function(cfg){
        if(!this._mainTab)
            this._mainTab = Ext._create('Ext.Panel',{
                layout: 'form',
                title: 'Atendimento',
                border: false,
                frame: true,
                scope: this,
                height: 520,
                items: [
                    this.getItemsMainPanel(cfg)
                ]
            });
        return this._mainTab;
    },

    getFormPanel: function(cfg) {
        if(!this._formPanel) {
            this._formPanel = Ext._create('Ext.form.FormPanel', {
                border: false,
                frame: false,

                items: [{
                    xtype: 'tabpanel',
                    activeTab: 0,
                    items: this.getTabPanelItems(cfg)
                }]
            });
        }

        return this._formPanel;
    },

    getTabPanelItems: function(cfg){
        return [
            this.getMainPanel(cfg),
            this.getAttachmentGrid(cfg)
        ];
    },

    finalize: function() {
        Ext._create('common.saci.attendance.FinalizeWindow', {
            action: 'create',
            modal: true,
            oId: this.attendance(),
            callback: {
                success: {
                    scope: this,
                    fn: function(instance) {
                        core.invokeCallback((this.callback || {}).success);
                        this.close();
                    }
                }
            }
        }).show();
    },

    forwardExternal: function() {
        Ext._create('common.saci.attendance.ForwardExternalWindow', {
            action: 'create',
            modal: true,
            oId: this.attendance(),
            callback: {
                success: {
                    scope: this,
                    fn: function(instance) {
                        core.invokeCallback((this.callback || {}).success);
                        this.close();
                    }
                }
            }
        }).show();
    },

    forward: function() {
        Ext._create('common.saci.attendance.ForwardWindow', {
            action: 'create',
            modal: true,
            oId: this.attendance(),
            callback: {
                success: {
                    scope: this,
                    fn: function(instance) {
                        core.invokeCallback((this.callback || {}).success);
                        this.close();
                    }
                }
            }
        }).show();
    },

    getFinalizeButton: function(cfg) {
        if(!this._finalizeButton)
            this._finalizeButton = Ext._create('Ext.Button', {
                text: 'Finalizar',
                scope: this,
                handler: this.finalize,
                disabled: true
            });

        return this._finalizeButton;
    },

    getForwardButton: function(cfg) {
        if(!this._forwardButton)
            this._forwardButton = Ext._create('Ext.Button', {
                text: 'Encaminhamento interno',
                scope: this,
                handler: this.forward,
                disabled: true
            });

        return this._forwardButton;
    },

    getForwardExternalButton: function(cfg) {
        if(!this._forwardExternalButton)
            this._forwardExternalButton = Ext._create('Ext.Button', {
                text: 'Encaminhamento externo',
                scope: this,
                handler: this.forwardExternal,
                disabled: true
            });

        return this._forwardExternalButton;
    },

    attendance: function(value, dispatch) {
        dispatch = (dispatch === undefined ? true : dispatch);

        if(value !== undefined) {
            this._attendance = value;

            if(dispatch)
                this.observeAttendance();
        }

        return this._attendance;
    },

    observeAttendance: function() {
        var value = this.attendance();

        this.changeButtons(value);
        this.loadAttachment(value);
    },

    getItemsButton: function(cfg) {
        return [
            this.getFinalizeButton(cfg),
            this.getForwardExternalButton(cfg),
            this.getForwardButton(cfg)
        ];
    },

    getButtons: function(cfg) {
        if(!this._buttons)
            this._buttons = [
                this.getItemsButton(cfg),
                '->',
            ].concat(common.saci.attendance.Window.superclass.getButtons.call(this, cfg));

        return this._buttons;
    },

    changeButtons: function(value) {
        if(value){
            this.getFinalizeButton().enable();
            this.getForwardButton().enable();
            this.getForwardExternalButton().enable();
        } else {
            this.getFinalizeButton().disable();
            this.getForwardButton().disable();
            this.getForwardExternalButton().disable();
        }
    },

    /*
     * Este campo lista os tipos de controles que usuário poderá
     * utilizar para classificar ou reclassificar o controle de
     * acesso de um atendimento.
     * 
     * Como não é um campo original do modelo Attendance, ele
     * está sendo configurado para não submeter seu valor.
     */
    getControlTypeField: function (cfg) {
        if (!this._controlTypeField) {
            var self = this;

            this._controlTypeField = Ext._create('core.fields.ComboField', {
                name: 'control_type',
                fieldLabel: 'Nível de acesso',
                emptyText: 'Deixe em branco para classificar como público',
                allowBlank: true,
                displayField: 'title',
                rest: 'common.document_access.controltype.byUser.Restful',
                anchor: '98%',
                submitValue: false,  // Não submeter.
                listeners: {
                    scope: this,
                    change: function(field, newValue, oldValue) {
                        this._controlTypeField._newValue = newValue;
                        this._controlTypeField._oldValue = oldValue;
                    }
                }
            });

            // Força a exibição do Nível de Acesso, mesmo que 
            // o usuário não tenha permissão para usá-lo.
            // Ver implementação da action get_query no 
            // controller DAControlTypeByUser.
            this._controlTypeField.store.baseParams = {
                control_type: ((cfg || {}).values || {}).control_type || 0
            };

            this._controlTypeField.getStore().on({
                load: function (store) {
                    store.insert(
                        0,
                        Ext._create('Ext.data.Record', {
                            pk: 0,
                            title: 'Público',
                            unicode: 'Público'
                        })
                    );
                }
            });

            /**
             * Desfaz a última mudança do valor do ComboBox.
             */
            this._controlTypeField.undoChange = function () {
                if (self._controlTypeField._oldValue !== undefined) {
                    self._controlTypeField.setValue(self._controlTypeField._oldValue);
                }
            }

            /**
             * Verifica se houve mudança no valor do ComboBox.
             * @return {boolean} Retorna true uma vez para cada mudança.
             */
            this._controlTypeField.wasChanged = function () {
                var result = (self._controlTypeField._oldValue !== self._controlTypeField._newValue);
                self._controlTypeField._newValue = self._controlTypeField._oldValue;
                return result;
            }
        }

        return this._controlTypeField;
    },

    getControlContainer: function (cfg) {
        if (!this._controlContainer) {
            this._controlContainer = Ext._create('Ext.Container', {
                layout: 'hbox',
                items: [
                    {
                        xtype: 'container',
                        layout: 'form',
                        flex: 3.0,
                        items: this.getControlTypeField(cfg)
                    },
                    {
                        xtype: 'container',
                        layout: 'form',
                        flex: 1.0,
                        items: this.getAllowedListButton(cfg)
                    }
                ]
            });
        }

        return this._controlContainer;
    },

    showAllowedListWindow: function (cfg) {
        var control = ((cfg || {}).values || {}).control || 0;

        Ext._create('common.document_access.allowedlistitem.Modal', {
            control: control,
            title: 'Credenciais de acesso',
            gridConfig: {
                allowUpdate: false,
                allowRemove: false,
                columnAction: false,
            }
        }).show();
    },

    getAllowedListButton: function (cfg) {
        if (!this._allowedListButton) {
            var control = ((cfg || {}).values || {}).control || 0;

            this._allowedListButton = Ext._create('Ext.Button', {
                text: 'Credenciais de acesso',
                width: 150,
                iconCls: 'icon-document_access icon-document_access-allowedlist',
                scope: this,
                disabled: (control ? false : true),
                handler: function() {
                    this.showAllowedListWindow(cfg);
                }
            });
        }

        return this._allowedListButton;
    },

    accessControl: function(values) {
        var rest = Ext._create('common.saci.attendance.Restful');
        var mask = new Ext.LoadMask(this.getEl(), {msg: 'Classificando informação...'});

        mask.show();
        rest.accessControl(
            this.oId,
            values,
            {
                scope: this,
                fn: function(result) {
                    if (result.success) {
                        this.getAllowedListButton().enable();

                        if (this.ownerGrid) {
                            this.ownerGrid.getStore().reload();
                        }
                    } else {
                        this.getControlTypeField().undoChange();

                        Ext.Msg.show({
                            title: 'Classificando informação',
                            msg: result.message,
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK
                        });
                    }
                }
            },
            {
                scope: this,
                fn: function(message) {
                    this.getControlTypeField().undoChange();

                    Ext.Msg.show({
                        title: 'Classificando informação',
                        msg: message,
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK
                    });
                }
            },
            {
                scope: this,
                fn: function() {
                    mask.hide();
                }
            }
        );
    },

    hasControlTypeChanged: function () {
        var controlType = this.getControlTypeField().getValue();
        return (this.getControlTypeField().wasChanged() && controlType);
    },

    showJustificationWindow: function () {
        var controlType = this.getControlTypeField().getValue();

        Ext._create('common.document_access.JustificationWindow', {
            title: 'Classificação de informação',
            scope: this,
            controlType: controlType,
            showDialogWhenCanceling: true,
            handler: function (justification, legalPrerogative) {
                this.accessControl({
                    control_type: controlType,
                    legal_prerogative: legalPrerogative,
                    justification: justification,
                });
            },
            failure: function (error) {
                this.getControlTypeField().undoChange();
            }
        }).show();
    },

    saveAndContinueCallback: function (instance) {
        this.action = 'update';
        this.oId = instance.pk;
        this.attendance(instance.pk);

        if (this.hasControlTypeChanged()) {
            this.showJustificationWindow();
        }
    },

    postConstructor: function (cfg) {
        if (cfg.oId || this.oId) {
            this.attendance(cfg.oId || this.oId);
        }
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.applyIf(
            cfg,
            {
                buttonAlign: 'left',
                disableSaveAndNew: true,
                saveAndContinue: {
                    scope: this,
                    fn: this.saveAndContinueCallback
                },
                border: false
            }
        );

        common.saci.attendance.Window.superclass.constructor.call(this, cfg);
        this.postConstructor(cfg);
    }
});

/*
 * src: /app/root/common/static/saci/attendance/Grid.js
 */

Ext._define('common.saci.attendance.Grid', {
    extend: 'core.RestfulGrid',

    restWindow: 'common.saci.attendance.Window',

    configOrderToolBar: ['add', 'edit', 'remove', '-', 'search', 'historic', '-', 'print'],
    keywordFieldMessage: 'Pesquisar',

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: '', dataIndex: 'icons', width: 26, renderer: core.rendererIconGrid, menuDisabled: true},
                    {header: 'Protocolo', dataIndex: 'protocol_unicode', width: 130},
                    {header: 'Assunto', dataIndex: 'subject', id: 'autoExpandColumn'},
                    {header: 'Iniciado em', dataIndex: 'created_at', width: 110, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i')},
                    {header: 'Finalizado em', dataIndex: 'signed_at', width: 110, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i')},
                ]
            );

        return this._columnModel;
    },

    getPrintAction: function() {
        if(!this._printAction){
            this._printAction = new Ext.Button({
                xtype: 'button',
                text: 'Imprimir',
                iconCls: 'icon-saci icon-saci-printer',
                scope: this,
                handler: this.printAttendance
            });
        }
        return this._printAction;
    },

    getHistoricAction: function() {
        if(!this._historicAction){
            this._historicAction = new Ext.Button({
                xtype: 'button',
                text: 'Histórico de encaminhamento',
                iconCls: 'icon-saci icon-saci-historic',
                scope: this,
                handler: this.openHistoricStepWindow
            });
        }
        return this._historicAction;
    },

    openHistoricStepWindow: function() {
        var selected = this.getSelectionModel().getSelected();

        if(selected) {
            Ext._create('common.saci.attendance.HistoricStepWindow', {
                action: 'create',
                modal: true,
                attendance: selected.get('pk'),
                callback: {
                    success: {
                        scope: this,
                        fn: function(instance) {
                            core.invokeCallback((this.callback || {}).success);
                            this.close();
                        }
                    }
                }
            }).show();
        } else {
            Ext.Msg.show({
                title: 'Histórico de encaminhamento',
                msg: 'Primeiro selecione o atendimento que deseja visualizar o histórico de encaminhamento.',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK
            });
        }

    },

    printAttendance: function(){
        var selected = this.getSelectionModel().getSelected();

        if(selected) {
            var wnd = window.open(
                '/athenas/SACIAttendanceRestful/renderer_document_to_print/?attendance=' + selected.get('pk'),
                '_to_printer',
                (new SquareScreen(0.85)).toString() + ', scrollbars=yes'
            );

            if(!wnd)
                Ext.Msg.show({
                    title: 'Preparando para imprimir',
                    msg: 'Não foi possivel preparar o documento para impressão, devido ao bloqueador de popup.',
                    icon: Ext.Msg.ERROR,
                    buttons: Ext.Msg.OK
                });
            else
                wnd.onload = wnd.print;
        }
        else {
            Ext.Msg.show({
                title: 'Imprimir Atendimento',
                msg: 'Primeiro selecione o atendimento que deseja Imprimir.',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK
            });
        }
    },

    _hasRestrictedRecords: function (record) {
        if (record instanceof Ext.Button) {
            record = undefined;
        }

        var selections = core.nullValue(
            record,
            this.getSelectionModel().getSelections()
        );

        if (!Ext.isArray(selections)) {
            selections = [selections];
        }

        var restrictedExists = false;
        selections.forEach(function (value) {
            if (!value.data.can_read) {
                restrictedExists = true;
            }
        });

        return restrictedExists;
    },

    /**
     * Método sobrescrito para se adequar ao Controle de Acesso.
     */
    updateItem: function(record) {
        if (!this.allowUpdate) {
            return;
        }

        if (this._hasRestrictedRecords(record)) {
            Ext.Msg.show({
                title: 'Classificando informação',
                msg: 'Este documento possui controle de acesso.',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK
            });
        } else {
            common.saci.attendance.Grid.superclass.updateItem.call(this, record);
        }
    },

    /**
     * Método sobrescrito para se adequar ao Controle de Acesso.
     */
    removeItems: function(record, cfg) {
        if (!this.allowRemove) {
            return;
        }

        if (this._hasRestrictedRecords(record)) {
            Ext.Msg.show({
                title: 'Classificando informação',
                msg: 'Este documento possui controle de acesso.',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK
            });
        } else {
            common.saci.attendance.Grid.superclass.removeItems.call(this, record, cfg);
        }
    }
});

